READ={'preflight','status','foreground','window','lock-status','runtime-contract','record-status'}
COMMON={'snapshot-evidence','ui-evidence','evidence-bundle'}
PHONE={
 'preflight':READ|COMMON|{'lock-acquire','lock-acquire-new','open-app','account-current'},
 'collect_videos':READ|COMMON|{'open-search','search-video-tab','search-time-layer','search-video-cards','tap-evidence','current-video-link','back-to-results','back-evidence','swipe-evidence','lock-refresh'},
 'dedup':READ|COMMON|{'open-video','current-video-link','lock-refresh'},
 'qualification':READ|COMMON|{'open-video','open-app','close-app','current-video-link','record-start','record-stop','record-extract-audio','native-audio-evidence','tap-evidence','swipe-evidence','lock-refresh'},
 'collection':READ|COMMON|{'open-video','current-video-link','open-comments','collect-comments','commenter-identity','back-evidence','swipe-evidence','lock-refresh'},
 'cleanup':READ|COMMON|{'record-stop','close-app','return-safe-desktop','lock-release-exact','lock-refresh'},
}
GUARDED={'open-app','account-current','snapshot-evidence','ui-evidence','close-app','return-safe-desktop','current-video-link','record-start','record-stop','record-extract-audio','native-audio-evidence'}
EIDS={'account-current':1,'snapshot-evidence':1,'ui-evidence':1,'search-video-tab':1,'search-time-layer':2,'search-video-cards':1,'tap-evidence':3,'current-video-link':1,'open-video':2,'record-start':1,'record-status':1,'record-stop':1,'record-extract-audio':1,'native-audio-evidence':1,'open-comments':1,'collect-comments':1,'commenter-identity':4,'back-to-results':1,'back-evidence':1,'swipe-evidence':6}
OPS={
 'preflight':{'company_config'},
 'collect_videos':{'discover','discover_readback','inspect_videos'},
 'dedup':{'inspect_videos','claim_videos','renew_video'},
 'qualification':{'inspect_videos','renew_video'},
 'collection':{'inspect_videos','renew_video','collect_partial','sample_readback','certify_collected_comment','certify_collected_comment_readback'},
 'scoring':{'company_config','score_scope','score','score_recovery','score_readback','score_exclusion_readback'},
 'mark_leads':{'policy_review','score_readback','mark_leads','mark_readback','bridge_outreach','bridge_readback'},
 'cleanup':{'inspect_videos','release_video'},
}
def phone_args(c,activity,args,*,reject=ValueError):
 allowed=PHONE.get(activity,set())
 if c['assigned_workflow']=='104' and activity=='send_dm':allowed=READ|COMMON|{'account-current','lock-refresh'}
 if c['assigned_workflow']=='104' and activity=='write_back':allowed=READ
 if activity=='collection' and c.get('recovery',{}).get('collection',{}).get('existing_comment_id'):allowed=READ|COMMON|{'open-video','current-video-link','back-evidence','commenter-profile-card-link','lock-refresh'}
 if not args or args[0] not in allowed:raise reject('PHONE_OPERATION_SCOPE')
 if activity=='qualification' and args[0]=='swipe-evidence':
  if len(args) not in [7,8] or not all(v.isdigit() for v in args[1:6]) or args[2]!=args[4] or not 0<=int(args[3])<int(args[1]) or not 1<=int(args[5])<=1500:raise reject('SEEK_START_ONLY')
 cmd=args[0];run=c['tasks'][c['assigned_workflow']]['run_tag']
 if cmd=='commenter-profile-card-link':
  target=c['recovery']['collection']
  if len(args)!=6 or args[1:5]!=[target['video_id'],target['expected_douyin_id'],target['expected_nickname_b64'],target['comment_body_sha256']]:raise reject('METADATA_PHONE_SCOPE')
  if not args[5].startswith(target['evidence_prefix']+'-'):raise reject('METADATA_EVIDENCE_SCOPE')
 if cmd in EIDS:
  at=EIDS[cmd]
  if len(args)<=at or not args[at].startswith(run+'-'):raise reject('EVIDENCE_RUN_SCOPE')
  if activity=='collection' and c.get('recovery',{}).get('collection',{}).get('existing_comment_id') and not args[at].startswith(c['recovery']['collection']['evidence_prefix']+'-'):raise reject('METADATA_EVIDENCE_SCOPE')
 if cmd in {'lock-acquire','lock-acquire-new','lock-release-exact','lock-refresh'} and args[1:]!=[c['local_owner']]:raise reject('LOCAL_OWNER_SCOPE')
 if cmd=='open-video' and args[1] not in c['verification'].get('102',{}).get('video_ids',[]):raise reject('VIDEO_SCOPE')
 return ['--profile',c['profile']]+(['--lock-owner',c['local_owner']] if cmd in GUARDED or cmd=='commenter-profile-card-link' else [])+args

def business_operations(c,activity):
 if activity=='collection' and c.get('recovery',{}).get('collection',{}).get('existing_comment_id'):
  return {'complete_collected_comment_metadata','complete_collected_comment_metadata_readback'}
 return OPS.get(activity,set())

def scoped_business(c,activity,i,*,reject=ValueError):
 stage=c['assigned_workflow'];run=c['tasks'][stage]['run_tag']
 if stage=='104':raise reject('USE_SCOPED_OUTREACH_TOOL')
 if activity=='collection' and c.get('recovery',{}).get('collection',{}).get('existing_comment_id'):
  target=c['recovery']['collection']
  if i.get('op') not in business_operations(c,activity) or i.get('comment_id')!=target['existing_comment_id'] or i.get('video_id')!=target['video_id'] or i.get('video_url')!='https://www.douyin.com/video/'+target['video_id']:raise reject('METADATA_BUSINESS_SCOPE')
  if i['op']=='complete_collected_comment_metadata':
   if 'before_snapshot' in i and i['before_snapshot']!=target['before_snapshot']:raise reject('METADATA_BEFORE_CHANGED')
   if 'before_sha256' in i and i['before_sha256']!=target['before_sha256']:raise reject('METADATA_BEFORE_CHANGED')
   i={**i,'before_snapshot':target['before_snapshot'],'before_sha256':target['before_sha256']}
 else:
  if i.get('op') not in business_operations(c,activity):raise reject('BUSINESS_ACTIVITY_SCOPE')
 if i.get('run',run)!=run or i.get('line',c.get('line'))!=c.get('line'):raise reject('BUSINESS_RUN_SCOPE')
 x={**i,'run':run,'line':c.get('line')}
 if x.get('limit',1) not in range(1,c['max_candidates']+1):raise reject('LIMIT')
 for key in ['comments','ids','comment_ids','committed_partial_ids']:
  if len(x.get(key,[]))>c['comment_limit']:raise reject('COMMENT_LIMIT')
 if x['op']=='score' and x.get('budget_max')!=1:raise reject('SINGLE_SCORE_REQUIRED')
 allowed=c['verification'].get(stage,{}).get('video_ids',[])
 if stage=='102' and (x.get('video_id') and x['video_id'] not in allowed or any(v not in allowed for v in x.get('video_ids',[]))):raise reject('VIDEO_SCOPE')
 if stage=='103':
  scope=c['verification']['103'];ids=scope['comment_ids']
  for key in ['ids','comment_ids','committed_partial_ids']:
   if any(v not in ids for v in x.get(key,[])):raise reject('COMMENT_SCOPE')
  if 'sources' in x and x['sources']!=scope['sources']:raise reject('SOURCE_SCOPE')
 return x
